<script setup lang="ts">
/**
 * The modal that appears when it's a user's birthday, is triggered by selecting
 * the birthday notification bell in the navigation bar.
 */

import { gsap, CustomEase, CustomBounce } from "gsap/all";
import type GSAPTimeline from "gsap";

// eslint-disable-next-line @typescript-eslint/no-unsafe-argument -- The plugins import as <any> so we need to ignore this
gsap.registerPlugin(CustomEase, CustomBounce); // Register the custom plugins otherwise they won't work

const emit = defineEmits<{
    revealed: [];
}>();

let cakeTimeline: GSAPTimeline; // the timeline for the cake animation
let afterCakeTimeline: GSAPTimeline; // the timeline triggered after (onComplete) the cake animation

/**
 * Emit to start showing the stars in the background and pop up the happy birthday message,
 * also popping the modal and flicking the candles
 */
function onCakeAnimated(): void {
    emit("revealed"); // to start showing the stars in the background
    afterCakeTimeline = gsap.timeline();
    afterCakeTimeline.to("#happy-birthday", { duration: 2, scale: 1, ease: "elastic.out" });
    afterCakeTimeline.to("#cake", { duration: 2, scale: 1, ease: "elastic.out" }, "<3%");
    if (document.querySelector("[data-reveal]")) {
        // pop out the modal
        afterCakeTimeline.to(
            "[data-reveal]",
            { duration: 2, scale: 1.05, yoyo: true, repeat: 1, ease: "elastic.out" },
            "<3%",
        );
    }
    // animate the candles flickering
    afterCakeTimeline.to(
        "#cake__middle-flame",
        {
            duration: 0.3,
            scaleY: 0.85,
            opacity: 0.8,
            yoyo: true,
            repeat: -1,
            delay: 0.1,
            ease: "power2.inOut",
        },
        0,
    );
    afterCakeTimeline.to(
        "#cake__left-flame",
        {
            duration: 0.3,
            scaleY: 0.85,
            opacity: 0.8,
            yoyo: true,
            repeat: -1,
            ease: "power2.inOut",
        },
        0,
    );
    afterCakeTimeline.to(
        "#cake__right-flame",
        {
            duration: 0.3,
            scaleY: 0.85,
            opacity: 0.8,
            yoyo: true,
            delay: 0.2,
            repeat: -1,
            ease: "power2.inOut",
        },
        0,
    );
}

/**
 * Animate the cake
 * see https://gsap.com/docs/v3/GSAP/Timeline/ for more information on timelines
 */
function animateCake(): void {
    // create a custom bounce ease for the cake slices landing
    // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access -- The plugin is imported as <any> so we need to ignore this
    CustomBounce.create("myBounce", {
        strength: 0.1,
        squash: 0.3,
        squashID: "myBounce-squash",
    });
    cakeTimeline = gsap.timeline({ delay: 0.5, onComplete: onCakeAnimated });
    // bring the cake plate up from the bottom
    cakeTimeline.from("#cake__plate", {
        y: 100,
        scale: 0.8,
        rotate: 10,
        transformOrigin: "center bottom",
        ease: "power2.inOut",
        duration: 0.8,
    });
    // bring the cake slices down from the top
    cakeTimeline.from(
        "#cake__base",
        {
            y: -350,
            rotate: -20,
            transformOrigin: "center bottom",
            ease: "myBounce",
            duration: 0.9,
        },
        "<10%",
    );
    cakeTimeline.from(
        "#cake__middle",
        {
            y: -350,
            rotate: 20,
            transformOrigin: "center bottom",
            ease: "myBounce",
            duration: 0.9,
        },
        "<25%",
    );
    cakeTimeline.from(
        "#cake__top",
        {
            y: -350,
            rotate: -20,
            transformOrigin: "center bottom",
            ease: "myBounce",
            duration: 0.9,
        },
        "<25%",
    );
    // pop up the candles
    cakeTimeline.from(
        "#cake__middle-candle",
        {
            opacity: 0,
            scale: 0.8,
            y: 30,
            ease: "power1.inOut",
            transformOrigin: "center bottom",
            duration: 0.5,
        },
        "<75%",
    );
    cakeTimeline.from(
        "#cake__left-candle",
        {
            opacity: 0,
            scale: 0.8,
            y: 30,
            ease: "power1.inOut",
            transformOrigin: "center bottom",
            duration: 0.5,
        },
        "<25%",
    );
    cakeTimeline.from(
        "#cake__right-candle",
        {
            opacity: 0,
            scale: 0.8,
            y: 30,
            ease: "power1.inOut",
            transformOrigin: "center bottom",
            duration: 0.5,
        },
        "<25%",
    );
    // then light the candles
    cakeTimeline.from("#cake__middle-flame", {
        opacity: 0,
        scale: 0.7,
        ease: "power2.out",
        transformOrigin: "center bottom",
        duration: 0.5,
    });
    cakeTimeline.from(
        "#cake__right-flame",
        {
            opacity: 0,
            scale: 0.6,
            ease: "power2.out",
            transformOrigin: "center bottom",
            duration: 0.5,
        },
        "<25%",
    );
    cakeTimeline.from(
        "#cake__left-flame",
        {
            opacity: 0,
            scale: 0.8,
            ease: "power2.out",
            transformOrigin: "center bottom",
            duration: 0.5,
        },
        "<25%",
    );
}

/**
 * Initialize the animations when the component is mounted
 */
window.Vue.onMounted(() => {
    gsap.set("#happy-birthday", { scale: 0 }); // hide the text for later reveal
    gsap.set("#cake", { scale: 0.9 }); // to full scale when the text is revealed
    animateCake();
});

/**
 * When the component is unmounted, ensure all the animations are cleared
 */
window.Vue.onBeforeUnmount(() => {
    cakeTimeline.kill();
    afterCakeTimeline.kill();
});
</script>

